/* Configuration of the MCP runtime, from the environment only. Generated by gherkin-ai (ghk expose generate).
 * No secret has a default, and none is ever logged. Credentials arrive as environment variables that your
 * platform fills from its secret store (AgentCore Identity, Secrets Manager, Key Vault, Kubernetes secrets). */

export type UpstreamAuth = 'mint-hs256' | 'bearer' | 'none';

export interface RuntimeConfig {
  host: string;
  port: number;
  /** Which environment this runtime serves: a write runs only where its approval names this environment. */
  environment: string;
  /** Base URL of the service: the only host the runtime calls (no other URL is ever fetched for a tool). */
  upstreamUrl: URL;
  upstreamAuth: UpstreamAuth;
  /** mint-hs256: the service's own JWT secret (the generated kernels verify HS256 tokens). */
  upstreamJwtSecret?: string;
  /** bearer: a service credential for the backend. */
  upstreamToken?: string;
  upstreamAudience?: string;
  /** OIDC issuer of the callers' tokens, and the audiences or client ids accepted. */
  issuer: string;
  audiences: string[];
  jwksUrl?: string;
  /** Only for a local test issuer: allows http:// for the issuer and its keys. */
  allowInsecureIssuer: boolean;
  maxRequestBytes: number;
  maxResponseBytes: number;
  /** JSONL audit file; stdout when absent. */
  auditFile?: string;
  contextTools: boolean;
  contextScope: string;
  /** Public URL of /mcp, for the OAuth protected-resource metadata. */
  publicUrl?: string;
}

export class ConfigurationError extends Error {}

function required(env: NodeJS.ProcessEnv, name: string): string {
  const value = env[name]?.trim();
  if (!value) throw new ConfigurationError(name + ' is required.');
  return value;
}

function int(env: NodeJS.ProcessEnv, name: string, fallback: number, min: number, max: number): number {
  const raw = env[name];
  if (raw === undefined || raw === '') return fallback;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < min || n > max) throw new ConfigurationError(name + ' must be an integer between ' + min + ' and ' + max + '.');
  return n;
}

const yes = (v: string | undefined) => v !== undefined && /^(1|true|yes)$/i.test(v.trim());

export function loadConfig(env: NodeJS.ProcessEnv = process.env, upstreamUrlEnv = 'GHK_UPSTREAM_URL'): RuntimeConfig {
  const upstreamUrl = new URL(required(env, upstreamUrlEnv));
  if (upstreamUrl.username || upstreamUrl.password) throw new ConfigurationError(upstreamUrlEnv + ' must not carry credentials.');
  if (upstreamUrl.protocol !== 'https:' && !(upstreamUrl.protocol === 'http:' && yes(env.GHK_UPSTREAM_ALLOW_HTTP))) {
    throw new ConfigurationError(upstreamUrlEnv + ' must be https (set GHK_UPSTREAM_ALLOW_HTTP=true for a private network you trust).');
  }
  if (upstreamUrl.search || upstreamUrl.hash) throw new ConfigurationError(upstreamUrlEnv + ' must be a base URL without query or fragment.');

  const upstreamAuth = (env.GHK_UPSTREAM_AUTH ?? 'mint-hs256') as UpstreamAuth;
  if (!['mint-hs256', 'bearer', 'none'].includes(upstreamAuth)) throw new ConfigurationError('GHK_UPSTREAM_AUTH must be mint-hs256, bearer or none.');
  const upstreamJwtSecret = upstreamAuth === 'mint-hs256' ? required(env, 'GHK_UPSTREAM_JWT_SECRET') : undefined;
  if (upstreamJwtSecret && upstreamJwtSecret.length < 32) throw new ConfigurationError('GHK_UPSTREAM_JWT_SECRET must be at least 32 characters.');
  const upstreamToken = upstreamAuth === 'bearer' ? required(env, 'GHK_UPSTREAM_TOKEN') : undefined;

  const issuer = required(env, 'GHK_OIDC_ISSUER').replace(/\/+$/, '');
  const allowInsecureIssuer = yes(env.GHK_OIDC_ALLOW_INSECURE);
  if (!issuer.startsWith('https://') && !allowInsecureIssuer) throw new ConfigurationError('GHK_OIDC_ISSUER must be https.');
  const audiences = required(env, 'GHK_OIDC_AUDIENCE').split(',').map(s => s.trim()).filter(Boolean);

  return {
    host: env.HOST ?? '0.0.0.0',
    port: int(env, 'PORT', 8000, 1, 65535),
    environment: required(env, 'GHK_ENVIRONMENT'),
    upstreamUrl,
    upstreamAuth,
    upstreamJwtSecret,
    upstreamToken,
    upstreamAudience: env.GHK_UPSTREAM_AUDIENCE || undefined,
    issuer,
    audiences,
    jwksUrl: env.GHK_OIDC_JWKS_URL || undefined,
    allowInsecureIssuer,
    maxRequestBytes: int(env, 'GHK_MAX_REQUEST_BYTES', 256 * 1024, 1024, 10 * 1024 * 1024),
    maxResponseBytes: int(env, 'GHK_MAX_RESPONSE_BYTES', 1024 * 1024, 1024, 20 * 1024 * 1024),
    auditFile: env.GHK_AUDIT_FILE || undefined,
    contextTools: env.GHK_CONTEXT_TOOLS === undefined ? true : yes(env.GHK_CONTEXT_TOOLS),
    contextScope: env.GHK_CONTEXT_SCOPE || 'bdd:read',
    publicUrl: env.GHK_PUBLIC_URL || undefined
  };
}
